-- =============================================================================
-- Migration: Wave 0.1 — Canon Full-Run Schema
-- Version:   v6.3.x
-- Target:    MemberJunction Core (${flyway:defaultSchema})
-- Purpose:
--   1. Add ${flyway:defaultSchema}.GraphPermission for per-graph Read / Use / Approve access control.
--   2. Add ${flyway:defaultSchema}.SearchScopeGraph for dedicated SearchScope -> Graph lane bindings.
--   3. Deliver MJ 6213 memory & learning-cycle schema additions:
--      - ${flyway:defaultSchema}.AIAgentNoteSource + OPENJSON / ConsolidatedIntoNoteID backfill
--      - Additive cycle telemetry columns on ${flyway:defaultSchema}.AIAgentLearningCycle
--      - ${flyway:defaultSchema}.AIAgentLearningCycleProposal (quarantine ledger, Self-Improvement Memory, Rule 6 scoring/routing/briefs)
--      - ${flyway:defaultSchema}.AIAgentLearningCycleProposalSource (exclusive-arc real FKs + polymorphic escape hatch)
--      - ${flyway:defaultSchema}.AIAgentContextItem (per-run and per-session retrieval/citation traces)
--      - Canon authority columns on ${flyway:defaultSchema}.AIAgentNote and ${flyway:defaultSchema}.AISkill
--      - AllowInFlightMemorySearch flag on ${flyway:defaultSchema}.AIAgent
--   4. Add nullable EffectiveFrom / EffectiveTo validity window columns on ${flyway:defaultSchema}.GraphConcept.
--   5. Add nullable AuthorityTierID override column on ${flyway:defaultSchema}.GraphEdge.
--   6. Extend CK_GraphConcept_Status and CK_GraphEdge_Status to include 'Provisional'.
--   7. Add StaleMemberPolicy and PublishNonHumanApprovals settings on ${flyway:defaultSchema}.Graph.
--   8. Update spDeleteEntityWithCoreDependencies for new Entity FKs and dependent child tables.
-- =============================================================================


-- =============================================================================
-- 1. GraphPermission
-- =============================================================================
CREATE TABLE [${flyway:defaultSchema}].[GraphPermission] (
    [ID]              UNIQUEIDENTIFIER NOT NULL CONSTRAINT [DF_GraphPermission_ID] DEFAULT (NEWSEQUENTIALID()),
    [GraphID]         UNIQUEIDENTIFIER NOT NULL,
    [UserID]          UNIQUEIDENTIFIER NULL,
    [RoleID]          UNIQUEIDENTIFIER NULL,
    [PermissionLevel] NVARCHAR(20)     COLLATE SQL_Latin1_General_CP1_CI_AS NOT NULL,
    CONSTRAINT [PK_GraphPermission] PRIMARY KEY CLUSTERED ([ID]),
    CONSTRAINT [FK_GraphPermission_Graph] FOREIGN KEY ([GraphID])
        REFERENCES [${flyway:defaultSchema}].[Graph]([ID]),
    CONSTRAINT [FK_GraphPermission_User] FOREIGN KEY ([UserID])
        REFERENCES [${flyway:defaultSchema}].[User]([ID]),
    CONSTRAINT [FK_GraphPermission_Role] FOREIGN KEY ([RoleID])
        REFERENCES [${flyway:defaultSchema}].[Role]([ID]),
    CONSTRAINT [CK_GraphPermission_Level]
        CHECK ([PermissionLevel] IN (N'None', N'Read', N'Use', N'Approve')),
    CONSTRAINT [CK_GraphPermission_Principal]
        CHECK (([UserID] IS NOT NULL AND [RoleID] IS NULL) OR ([UserID] IS NULL AND [RoleID] IS NOT NULL))
);
GO

CREATE UNIQUE NONCLUSTERED INDEX [UX_GraphPermission_Graph_User]
    ON [${flyway:defaultSchema}].[GraphPermission] ([GraphID], [UserID])
    WHERE ([UserID] IS NOT NULL);
GO

CREATE UNIQUE NONCLUSTERED INDEX [UX_GraphPermission_Graph_Role]
    ON [${flyway:defaultSchema}].[GraphPermission] ([GraphID], [RoleID])
    WHERE ([RoleID] IS NOT NULL);
GO


-- =============================================================================
-- 2. SearchScopeGraph
-- =============================================================================
CREATE TABLE [${flyway:defaultSchema}].[SearchScopeGraph] (
    [ID]            UNIQUEIDENTIFIER NOT NULL CONSTRAINT [DF_SearchScopeGraph_ID] DEFAULT (NEWSEQUENTIALID()),
    [SearchScopeID] UNIQUEIDENTIFIER NOT NULL,
    [GraphID]       UNIQUEIDENTIFIER NOT NULL,
    [Priority]      INT              NOT NULL CONSTRAINT [DF_SearchScopeGraph_Priority] DEFAULT ((100)),
    [MaxResults]    INT              NULL,
    CONSTRAINT [PK_SearchScopeGraph] PRIMARY KEY CLUSTERED ([ID]),
    CONSTRAINT [FK_SearchScopeGraph_SearchScope] FOREIGN KEY ([SearchScopeID])
        REFERENCES [${flyway:defaultSchema}].[SearchScope]([ID]),
    CONSTRAINT [FK_SearchScopeGraph_Graph] FOREIGN KEY ([GraphID])
        REFERENCES [${flyway:defaultSchema}].[Graph]([ID]),
    CONSTRAINT [UQ_SearchScopeGraph_Scope_Graph] UNIQUE ([SearchScopeID], [GraphID])
);
GO


-- =============================================================================
-- 3.1 AIAgentNoteSource + Backfill from DerivedFromNoteIDs & ConsolidatedIntoNoteID
-- =============================================================================
CREATE TABLE [${flyway:defaultSchema}].[AIAgentNoteSource] (
    [ID]               UNIQUEIDENTIFIER NOT NULL CONSTRAINT [DF_AIAgentNoteSource_ID] DEFAULT (NEWSEQUENTIALID()),
    [NoteID]           UNIQUEIDENTIFIER NOT NULL,
    [SourceNoteID]     UNIQUEIDENTIFIER NOT NULL,
    [RelationshipType] NVARCHAR(30)     COLLATE SQL_Latin1_General_CP1_CI_AS NOT NULL CONSTRAINT [DF_AIAgentNoteSource_RelType] DEFAULT (N'Consolidated From'),
    [Sequence]         INT              NOT NULL CONSTRAINT [DF_AIAgentNoteSource_Sequence] DEFAULT ((0)),
    CONSTRAINT [PK_AIAgentNoteSource] PRIMARY KEY CLUSTERED ([ID]),
    CONSTRAINT [FK_AIAgentNoteSource_Note] FOREIGN KEY ([NoteID])
        REFERENCES [${flyway:defaultSchema}].[AIAgentNote]([ID]),
    CONSTRAINT [FK_AIAgentNoteSource_SourceNote] FOREIGN KEY ([SourceNoteID])
        REFERENCES [${flyway:defaultSchema}].[AIAgentNote]([ID]),
    CONSTRAINT [UQ_AIAgentNoteSource_Edge] UNIQUE ([NoteID], [SourceNoteID], [RelationshipType]),
    CONSTRAINT [CK_AIAgentNoteSource_NoSelfLoop] CHECK ([NoteID] <> [SourceNoteID]),
    CONSTRAINT [CK_AIAgentNoteSource_RelType]
        CHECK ([RelationshipType] IN (N'Consolidated From', N'Supersedes', N'Disambiguated From', N'Dream Synthesized From', N'Other'))
);
GO

;WITH DerivedPairs AS (
    SELECT
        n.[ID] AS [NoteID],
        src.[ID] AS [SourceNoteID],
        MIN(CAST(j.[key] AS INT)) AS [Sequence]
    FROM [${flyway:defaultSchema}].[AIAgentNote] AS n
    CROSS APPLY OPENJSON(n.[DerivedFromNoteIDs]) AS j
    INNER JOIN [${flyway:defaultSchema}].[AIAgentNote] AS src
        ON TRY_CAST(j.[value] AS UNIQUEIDENTIFIER) = src.[ID]
    WHERE n.[DerivedFromNoteIDs] IS NOT NULL
      AND ISJSON(n.[DerivedFromNoteIDs]) = 1
      AND LEFT(LTRIM(n.[DerivedFromNoteIDs]), 1) = N'['
      AND n.[ID] <> src.[ID]
    GROUP BY n.[ID], src.[ID]
)
INSERT INTO [${flyway:defaultSchema}].[AIAgentNoteSource] (
    [NoteID],
    [SourceNoteID],
    [RelationshipType],
    [Sequence]
)
SELECT
    dp.[NoteID],
    dp.[SourceNoteID],
    N'Consolidated From',
    dp.[Sequence]
FROM DerivedPairs AS dp
WHERE NOT EXISTS (
    SELECT 1
    FROM [${flyway:defaultSchema}].[AIAgentNoteSource] AS existing
    WHERE existing.[NoteID] = dp.[NoteID]
      AND existing.[SourceNoteID] = dp.[SourceNoteID]
      AND existing.[RelationshipType] = N'Consolidated From'
);
GO

INSERT INTO [${flyway:defaultSchema}].[AIAgentNoteSource] (
    [NoteID],
    [SourceNoteID],
    [RelationshipType],
    [Sequence]
)
SELECT
    src.[ConsolidatedIntoNoteID],
    src.[ID],
    N'Consolidated From',
    0
FROM [${flyway:defaultSchema}].[AIAgentNote] AS src
INNER JOIN [${flyway:defaultSchema}].[AIAgentNote] AS target
    ON target.[ID] = src.[ConsolidatedIntoNoteID]
WHERE src.[ConsolidatedIntoNoteID] IS NOT NULL
  AND src.[ID] <> src.[ConsolidatedIntoNoteID]
  AND NOT EXISTS (
      SELECT 1
      FROM [${flyway:defaultSchema}].[AIAgentNoteSource] AS existing
      WHERE existing.[NoteID] = src.[ConsolidatedIntoNoteID]
        AND existing.[SourceNoteID] = src.[ID]
        AND existing.[RelationshipType] = N'Consolidated From'
  );
GO


