                REFERENCES [${flyway:defaultSchema}].[AIAgentRun]([ID]),
        [ProposalsGenerated] INT NOT NULL
            CONSTRAINT [DF_AIAgentLearningCycle_PropGen] DEFAULT ((0)),
        [ProposalsVerified] INT NOT NULL
            CONSTRAINT [DF_AIAgentLearningCycle_PropVer] DEFAULT ((0)),
        [ProposalsApplied] INT NOT NULL
            CONSTRAINT [DF_AIAgentLearningCycle_PropApp] DEFAULT ((0)),
        [TotalCostUSD] DECIMAL(10, 4) NULL;
GO


-- =============================================================================
-- 3.3 AIAgentLearningCycleProposal
-- =============================================================================
CREATE TABLE [${flyway:defaultSchema}].[AIAgentLearningCycleProposal] (
    [ID]                       UNIQUEIDENTIFIER NOT NULL CONSTRAINT [DF_AIAgentProposal_ID] DEFAULT (NEWSEQUENTIALID()),
    -- Identity & Scope
    [LearningCycleID]          UNIQUEIDENTIFIER NOT NULL,
    [TargetAgentID]            UNIQUEIDENTIFIER NULL,
    [CompanyID]                UNIQUEIDENTIFIER NULL,
    [UserID]                   UNIQUEIDENTIFIER NULL,
    [PrimaryScopeEntityID]     UNIQUEIDENTIFIER NULL,
    [PrimaryScopeRecordID]     NVARCHAR(450)    COLLATE SQL_Latin1_General_CP1_CI_AS NULL,
    [SecondaryScopes]          NVARCHAR(MAX)    COLLATE SQL_Latin1_General_CP1_CI_AS NULL,
    -- Proposal Spec
    [ProposalType]             NVARCHAR(40)     COLLATE SQL_Latin1_General_CP1_CI_AS NOT NULL,
    [SamplerStrategy]          NVARCHAR(40)     COLLATE SQL_Latin1_General_CP1_CI_AS NOT NULL,
    [Title]                    NVARCHAR(255)    COLLATE SQL_Latin1_General_CP1_CI_AS NOT NULL,
    [Claim]                    NVARCHAR(MAX)    COLLATE SQL_Latin1_General_CP1_CI_AS NOT NULL,
    [TestablePrediction]       NVARCHAR(MAX)    COLLATE SQL_Latin1_General_CP1_CI_AS NULL,
    [ProposedPayload]          NVARCHAR(MAX)    COLLATE SQL_Latin1_General_CP1_CI_AS NOT NULL,
    [ClaimHash]                NVARCHAR(64)     COLLATE SQL_Latin1_General_CP1_CI_AS NOT NULL,
    -- Trust & Privacy
    [SourceTrustCeiling]       NVARCHAR(30)     COLLATE SQL_Latin1_General_CP1_CI_AS NOT NULL CONSTRAINT [DF_AIAgentProposal_TrustCeiling] DEFAULT (N'Provisional User'),
    [DistinctUserCount]        INT              NULL,
    -- REM Generation Signals
    [GeneratorMetadata]        NVARCHAR(MAX)    COLLATE SQL_Latin1_General_CP1_CI_AS NULL,
    [CrossModelAgreementCount] INT              NOT NULL CONSTRAINT [DF_AIAgentProposal_AgreementCount] DEFAULT ((1)),
    [IsSingleModelOutlier]     BIT              NOT NULL CONSTRAINT [DF_AIAgentProposal_Outlier] DEFAULT ((0)),
    [GateProbability]          DECIMAL(5, 4)    NULL,
    [FalsifierVerdict]         NVARCHAR(30)     COLLATE SQL_Latin1_General_CP1_CI_AS NULL,
    [FalsifierCritique]        NVARCHAR(MAX)    COLLATE SQL_Latin1_General_CP1_CI_AS NULL,
    -- RL Verification Scorecard
    [VerificationMethod]       NVARCHAR(30)     COLLATE SQL_Latin1_General_CP1_CI_AS NOT NULL CONSTRAINT [DF_AIAgentProposal_VerifyMethod] DEFAULT (N'None'),
    [ReplayTrialsCount]        INT              NOT NULL CONSTRAINT [DF_AIAgentProposal_Trials] DEFAULT ((0)),
    [ReplayWinsCount]          INT              NOT NULL CONSTRAINT [DF_AIAgentProposal_Wins] DEFAULT ((0)),
    [ReplayLossesCount]        INT              NOT NULL CONSTRAINT [DF_AIAgentProposal_Losses] DEFAULT ((0)),
    [ReplayWinDelta]           DECIMAL(6, 4)    NULL,
    [QueryCheckPassed]         BIT              NULL,
    [VerificationEvidence]     NVARCHAR(MAX)    COLLATE SQL_Latin1_General_CP1_CI_AS NULL,
    -- Self-Improvement Memory (v1.2)
    [ProblemKey]               NVARCHAR(200)    COLLATE SQL_Latin1_General_CP1_CI_AS NOT NULL,
    [ProblemSummary]           NVARCHAR(MAX)    COLLATE SQL_Latin1_General_CP1_CI_AS NULL,
    [Rationale]                NVARCHAR(MAX)    COLLATE SQL_Latin1_General_CP1_CI_AS NOT NULL,
    [PredictedEffect]          DECIMAL(6, 4)    NULL,
    [ObservedEffect]           DECIMAL(6, 4)    NULL,
    [EffectMetric]             NVARCHAR(100)    COLLATE SQL_Latin1_General_CP1_CI_AS NULL,
    [EvaluationContext]        NVARCHAR(MAX)    COLLATE SQL_Latin1_General_CP1_CI_AS NULL,
    [SupersedesProposalID]     UNIQUEIDENTIFIER NULL,
    -- Rule 6 Impact, Confidence, Routing & AI Reviewer
    [ImpactLevel]              NVARCHAR(20)     COLLATE SQL_Latin1_General_CP1_CI_AS NULL,
    [ImpactInputs]             NVARCHAR(MAX)    COLLATE SQL_Latin1_General_CP1_CI_AS NULL,
    [ConfidenceScore]          DECIMAL(5, 4)    NULL,
    [ConfidenceInputs]         NVARCHAR(MAX)    COLLATE SQL_Latin1_General_CP1_CI_AS NULL,
    [PromotionRoute]           NVARCHAR(30)     COLLATE SQL_Latin1_General_CP1_CI_AS NULL,
    [ReviewByDate]             DATETIMEOFFSET   NULL,
    [ReviewBrief]              NVARCHAR(MAX)    COLLATE SQL_Latin1_General_CP1_CI_AS NULL,
    [ProposingModelID]         UNIQUEIDENTIFIER NULL,
    [AIReviewerModelID]        UNIQUEIDENTIFIER NULL,
    [AIReviewerDecision]       NVARCHAR(20)     COLLATE SQL_Latin1_General_CP1_CI_AS NULL,
    [AIReviewerRationale]      NVARCHAR(MAX)    COLLATE SQL_Latin1_General_CP1_CI_AS NULL,
    [AIReviewerConfidence]     DECIMAL(5, 4)    NULL,
    [AIReviewedAt]             DATETIMEOFFSET   NULL,
    [HumanOverruleReason]      NVARCHAR(MAX)    COLLATE SQL_Latin1_General_CP1_CI_AS NULL,
    -- Lifecycle & Materialization
    [Status]                   NVARCHAR(30)     COLLATE SQL_Latin1_General_CP1_CI_AS NOT NULL CONSTRAINT [DF_AIAgentProposal_Status] DEFAULT (N'Draft'),
    [ApprovalRequestID]        UNIQUEIDENTIFIER NULL,
    [AppliedNoteID]            UNIQUEIDENTIFIER NULL,
    [AppliedSkillID]           UNIQUEIDENTIFIER NULL,
    [AppliedGraphConceptID]    UNIQUEIDENTIFIER NULL,
    [AppliedGraphEdgeID]       UNIQUEIDENTIFIER NULL,
    [AppliedEntityID]          UNIQUEIDENTIFIER NULL,
    [AppliedRecordID]          NVARCHAR(450)    COLLATE SQL_Latin1_General_CP1_CI_AS NULL,
    [AppliedAt]                DATETIMEOFFSET   NULL,

    CONSTRAINT [PK_AIAgentLearningCycleProposal] PRIMARY KEY CLUSTERED ([ID]),
    CONSTRAINT [FK_AIAgentProposal_LearningCycle] FOREIGN KEY ([LearningCycleID])
        REFERENCES [${flyway:defaultSchema}].[AIAgentLearningCycle]([ID]),
    CONSTRAINT [FK_AIAgentProposal_TargetAgent] FOREIGN KEY ([TargetAgentID])
        REFERENCES [${flyway:defaultSchema}].[AIAgent]([ID]),
    CONSTRAINT [FK_AIAgentProposal_Company] FOREIGN KEY ([CompanyID])
        REFERENCES [${flyway:defaultSchema}].[Company]([ID]),
    CONSTRAINT [FK_AIAgentProposal_User] FOREIGN KEY ([UserID])
        REFERENCES [${flyway:defaultSchema}].[User]([ID]),
    CONSTRAINT [FK_AIAgentProposal_PrimaryScopeEntity] FOREIGN KEY ([PrimaryScopeEntityID])
        REFERENCES [${flyway:defaultSchema}].[Entity]([ID]),
    CONSTRAINT [FK_AIAgentProposal_Supersedes] FOREIGN KEY ([SupersedesProposalID])
        REFERENCES [${flyway:defaultSchema}].[AIAgentLearningCycleProposal]([ID]),
    CONSTRAINT [FK_AIAgentProposal_ProposingModel] FOREIGN KEY ([ProposingModelID])
        REFERENCES [${flyway:defaultSchema}].[AIModel]([ID]),
    CONSTRAINT [FK_AIAgentProposal_AIReviewerModel] FOREIGN KEY ([AIReviewerModelID])
        REFERENCES [${flyway:defaultSchema}].[AIModel]([ID]),
    CONSTRAINT [FK_AIAgentProposal_ApprovalRequest] FOREIGN KEY ([ApprovalRequestID])
        REFERENCES [${flyway:defaultSchema}].[AIAgentRequest]([ID]),
    CONSTRAINT [FK_AIAgentProposal_AppliedNote] FOREIGN KEY ([AppliedNoteID])
        REFERENCES [${flyway:defaultSchema}].[AIAgentNote]([ID]),
    CONSTRAINT [FK_AIAgentProposal_AppliedSkill] FOREIGN KEY ([AppliedSkillID])
        REFERENCES [${flyway:defaultSchema}].[AISkill]([ID]),
    CONSTRAINT [FK_AIAgentProposal_AppliedConcept] FOREIGN KEY ([AppliedGraphConceptID])
        REFERENCES [${flyway:defaultSchema}].[GraphConcept]([ID]),
    CONSTRAINT [FK_AIAgentProposal_AppliedEdge] FOREIGN KEY ([AppliedGraphEdgeID])
        REFERENCES [${flyway:defaultSchema}].[GraphEdge]([ID]),
    CONSTRAINT [FK_AIAgentProposal_AppliedEntity] FOREIGN KEY ([AppliedEntityID])
        REFERENCES [${flyway:defaultSchema}].[Entity]([ID]),

    CONSTRAINT [CK_AIAgentProposal_NoSelfSupersede]
        CHECK ([SupersedesProposalID] IS NULL OR [SupersedesProposalID] <> [ID]),
    CONSTRAINT [CK_AIAgentProposal_PrimaryScope]
        CHECK ([PrimaryScopeRecordID] IS NULL OR [PrimaryScopeEntityID] IS NOT NULL),
    CONSTRAINT [CK_AIAgentProposal_AppliedPair]
        CHECK (([AppliedEntityID] IS NULL AND [AppliedRecordID] IS NULL) OR ([AppliedEntityID] IS NOT NULL AND [AppliedRecordID] IS NOT NULL)),
    CONSTRAINT [CK_AIAgentProposal_ProposalType]
        CHECK ([ProposalType] IN (
            N'Create Note', N'Supersede Notes', N'Promote To Canon', N'Draft Skill',
            N'Create Graph Edge', N'Create Canon Concept', N'Promote Workflow',
            N'Evolve Workflow', N'Resolve Graph Contradiction', N'Prompt Revision'
        )),
    CONSTRAINT [CK_AIAgentProposal_SamplerStrategy]
        CHECK ([SamplerStrategy] IN (
            N'Contradiction Resolution', N'Failed Run Cluster', N'Distant Note Pair',
            N'Graph Bridge Walk', N'Successful Trajectory', N'Cross User Pattern',
            N'Workflow Telemetry', N'Graph Overlay Conflict', N'Harness Refiner Probe',
            N'Taxonomy Import'
        )),
    CONSTRAINT [CK_AIAgentProposal_TrustCeiling]
        CHECK ([SourceTrustCeiling] IN (N'Untrusted External', N'Provisional User', N'Verified Active', N'Canonical')),
    CONSTRAINT [CK_AIAgentProposal_FalsifierVerdict]
        CHECK ([FalsifierVerdict] IS NULL OR [FalsifierVerdict] IN (N'Passed', N'Rejected', N'Needs Scope Narrowing')),
    CONSTRAINT [CK_AIAgentProposal_VerifyMethod]
        CHECK ([VerificationMethod] IN (N'Counterfactual Replay', N'Query Check', N'Hybrid', N'Manual Only', N'None')),
    CONSTRAINT [CK_AIAgentProposal_ImpactLevel]
        CHECK ([ImpactLevel] IS NULL OR [ImpactLevel] IN (N'Low', N'Medium', N'High', N'Critical')),
    CONSTRAINT [CK_AIAgentProposal_PromotionRoute]
        CHECK ([PromotionRoute] IS NULL OR [PromotionRoute] IN (N'Approved by Policy', N'Provisional', N'Human', N'Named Owner')),
    CONSTRAINT [CK_AIAgentProposal_ReviewerDecision]
        CHECK ([AIReviewerDecision] IS NULL OR [AIReviewerDecision] IN (N'Approve', N'Reject', N'Needs Revision')),
    CONSTRAINT [CK_AIAgentProposal_Status]
        CHECK ([Status] IN (
            N'Draft', N'Filtered Out', N'Verifying', N'Verification Failed',
            N'Awaiting Approval', N'Approved', N'Applied', N'Rejected', N'Rolled Back'
        ))
);
GO

