-- =============================================================================
-- 3.4 AIAgentLearningCycleProposalSource
-- =============================================================================
CREATE TABLE [${flyway:defaultSchema}].[AIAgentLearningCycleProposalSource] (
    [ID]                         UNIQUEIDENTIFIER NOT NULL CONSTRAINT [DF_ProposalSource_ID] DEFAULT (NEWSEQUENTIALID()),
    [ProposalID]                 UNIQUEIDENTIFIER NOT NULL,
    [Role]                       NVARCHAR(40)     COLLATE SQL_Latin1_General_CP1_CI_AS NOT NULL,
    [TrustTierAtSnapshot]        NVARCHAR(30)     COLLATE SQL_Latin1_General_CP1_CI_AS NOT NULL,
    [SourceNoteID]               UNIQUEIDENTIFIER NULL,
    [SourceAgentRunID]           UNIQUEIDENTIFIER NULL,
    [SourceConversationDetailID] UNIQUEIDENTIFIER NULL,
    [SourceGraphConceptID]       UNIQUEIDENTIFIER NULL,
    [SourceGraphEdgeID]          UNIQUEIDENTIFIER NULL,
    [SourceEntityID]             UNIQUEIDENTIFIER NULL,
    [SourceRecordID]             NVARCHAR(450)    COLLATE SQL_Latin1_General_CP1_CI_AS NULL,

    CONSTRAINT [PK_AIAgentProposalSource] PRIMARY KEY CLUSTERED ([ID]),
    CONSTRAINT [FK_ProposalSource_Proposal] FOREIGN KEY ([ProposalID])
        REFERENCES [${flyway:defaultSchema}].[AIAgentLearningCycleProposal]([ID]),
    CONSTRAINT [FK_ProposalSource_Note] FOREIGN KEY ([SourceNoteID])
        REFERENCES [${flyway:defaultSchema}].[AIAgentNote]([ID]),
    CONSTRAINT [FK_ProposalSource_AgentRun] FOREIGN KEY ([SourceAgentRunID])
        REFERENCES [${flyway:defaultSchema}].[AIAgentRun]([ID]),
    CONSTRAINT [FK_ProposalSource_ConvDetail] FOREIGN KEY ([SourceConversationDetailID])
        REFERENCES [${flyway:defaultSchema}].[ConversationDetail]([ID]),
    CONSTRAINT [FK_ProposalSource_GraphConcept] FOREIGN KEY ([SourceGraphConceptID])
        REFERENCES [${flyway:defaultSchema}].[GraphConcept]([ID]),
    CONSTRAINT [FK_ProposalSource_GraphEdge] FOREIGN KEY ([SourceGraphEdgeID])
        REFERENCES [${flyway:defaultSchema}].[GraphEdge]([ID]),
    CONSTRAINT [FK_ProposalSource_Entity] FOREIGN KEY ([SourceEntityID])
        REFERENCES [${flyway:defaultSchema}].[Entity]([ID]),

    CONSTRAINT [CK_ProposalSource_Role]
        CHECK ([Role] IN (N'Supporting Note', N'Contradicting Note', N'Failed Run', N'Exemplar Run', N'User Correction', N'Bridge Node', N'Other')),
    CONSTRAINT [CK_ProposalSource_TrustTier]
        CHECK ([TrustTierAtSnapshot] IN (N'Untrusted External', N'Provisional User', N'Verified Active', N'Canonical')),
    CONSTRAINT [CK_ProposalSource_PolymorphicPair]
        CHECK (([SourceEntityID] IS NULL AND [SourceRecordID] IS NULL) OR ([SourceEntityID] IS NOT NULL AND [SourceRecordID] IS NOT NULL)),
    CONSTRAINT [CK_ProposalSource_OneTarget]
        CHECK (
            (CASE WHEN [SourceNoteID]               IS NOT NULL THEN 1 ELSE 0 END) +
            (CASE WHEN [SourceAgentRunID]           IS NOT NULL THEN 1 ELSE 0 END) +
            (CASE WHEN [SourceConversationDetailID] IS NOT NULL THEN 1 ELSE 0 END) +
            (CASE WHEN [SourceGraphConceptID]       IS NOT NULL THEN 1 ELSE 0 END) +
            (CASE WHEN [SourceGraphEdgeID]          IS NOT NULL THEN 1 ELSE 0 END) +
            (CASE WHEN [SourceEntityID] IS NOT NULL AND [SourceRecordID] IS NOT NULL THEN 1 ELSE 0 END) = 1
        )
);
GO


