    CONSTRAINT [FK_AIAgentContextItem_ConvDetail] FOREIGN KEY ([ConversationDetailID])
        REFERENCES [${flyway:defaultSchema}].[ConversationDetail]([ID]),
    CONSTRAINT [FK_AIAgentContextItem_AgentNote] FOREIGN KEY ([AgentNoteID])
        REFERENCES [${flyway:defaultSchema}].[AIAgentNote]([ID]),
    CONSTRAINT [FK_AIAgentContextItem_AgentExample] FOREIGN KEY ([AgentExampleID])
        REFERENCES [${flyway:defaultSchema}].[AIAgentExample]([ID]),
    CONSTRAINT [FK_AIAgentContextItem_Skill] FOREIGN KEY ([SkillID])
        REFERENCES [${flyway:defaultSchema}].[AISkill]([ID]),
    CONSTRAINT [FK_AIAgentContextItem_GraphConcept] FOREIGN KEY ([GraphConceptID])
        REFERENCES [${flyway:defaultSchema}].[GraphConcept]([ID]),
    CONSTRAINT [FK_AIAgentContextItem_PromptPart] FOREIGN KEY ([ScopedPromptPartID])
        REFERENCES [${flyway:defaultSchema}].[ScopedPromptPart]([ID]),
    CONSTRAINT [FK_AIAgentContextItem_ItemEntity] FOREIGN KEY ([ItemEntityID])
        REFERENCES [${flyway:defaultSchema}].[Entity]([ID]),

    CONSTRAINT [CK_AIAgentContextItem_HasAnchor]
        CHECK ([AgentRunID] IS NOT NULL OR [AgentSessionID] IS NOT NULL),
    CONSTRAINT [CK_AIAgentContextItem_StepNeedsRun]
        CHECK ([AgentRunStepID] IS NULL OR [AgentRunID] IS NOT NULL),
    CONSTRAINT [CK_AIAgentContextItem_TurnNeedsSession]
        CHECK ([ConversationDetailID] IS NULL OR [AgentSessionID] IS NOT NULL),
    CONSTRAINT [CK_AIAgentContextItem_EventType]
        CHECK ([EventType] IN (N'Retrieved', N'Injected', N'Withheld', N'Cited', N'Other')),
    CONSTRAINT [CK_AIAgentContextItem_ItemType]
        CHECK ([ItemType] IN (N'Note', N'Example', N'Skill', N'Graph Concept', N'Scoped Prompt Part', N'Other')),
    CONSTRAINT [CK_AIAgentContextItem_PolymorphicPair]
        CHECK (([ItemEntityID] IS NULL AND [ItemRecordID] IS NULL) OR ([ItemEntityID] IS NOT NULL AND [ItemRecordID] IS NOT NULL)),
    CONSTRAINT [CK_AIAgentContextItem_OneTarget]
        CHECK (
            (CASE WHEN [AgentNoteID]        IS NOT NULL THEN 1 ELSE 0 END) +
            (CASE WHEN [AgentExampleID]     IS NOT NULL THEN 1 ELSE 0 END) +
            (CASE WHEN [SkillID]            IS NOT NULL THEN 1 ELSE 0 END) +
            (CASE WHEN [GraphConceptID]     IS NOT NULL THEN 1 ELSE 0 END) +
            (CASE WHEN [ScopedPromptPartID] IS NOT NULL THEN 1 ELSE 0 END) +
            (CASE WHEN [ItemEntityID] IS NOT NULL AND [ItemRecordID] IS NOT NULL THEN 1 ELSE 0 END) = 1
        )
);
GO

CREATE NONCLUSTERED INDEX [IX_AIAgentContextItem_Run_Event]
    ON [${flyway:defaultSchema}].[AIAgentContextItem] ([AgentRunID], [EventType]);
GO

CREATE NONCLUSTERED INDEX [IX_AIAgentContextItem_Session_Event]
    ON [${flyway:defaultSchema}].[AIAgentContextItem] ([AgentSessionID], [EventType]);
GO


