-- AIAgentLearningCycleProposal
EXEC sp_addextendedproperty @name = N'MS_Description',
    @value = N'Quarantine ledger and RL/Rule-6 promotion workbench for candidate notes, skills, graph concepts/edges, and harness revisions.',
    @level0type = N'SCHEMA', @level0name = N'${flyway:defaultSchema}',
    @level1type = N'TABLE',  @level1name = N'AIAgentLearningCycleProposal';
EXEC sp_addextendedproperty @name = N'MS_Description',
    @value = N'Record identifier within PrimaryScopeEntityID when the proposal is scoped to a single entity record.',
    @level0type = N'SCHEMA', @level0name = N'${flyway:defaultSchema}',
    @level1type = N'TABLE',  @level1name = N'AIAgentLearningCycleProposal',
    @level2type = N'COLUMN', @level2name = N'PrimaryScopeRecordID';
